head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.colorCnt = 0; // 조회한 이후에만 컬럼에  color 변경하기 위한 변수
// 화면 리사이징

scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp = js_market;
scwin.gAcptNo;
// 현금배당

// 컬럼 컬러 구분을 위한 변수
scwin.check1, scwin.check2, scwin.check3, scwin.check4, scwin.check5, scwin.check6, scwin.check7, scwin.check8, scwin.check9, scwin.check10, scwin.check11, scwin.check12, scwin.check13, scwin.check14, scwin.check15, scwin.check16, scwin.check17;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // fn_com_isur(txb_ISUR_CD, txb_COM_NM);    //법인코드 및 법인명(회사명) 관련
        Grd_com_isur.style.zIndex = 30;
        $c.cm.PanelToGroupBox(panel_1); // 검색조건 패널에 스타일 적용

        await scwin.setCode(); // 공시일자(from~to)
        scwin.init(); // 시장구분
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF25106.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    rdo_MKT_ID.setValue(scwin.gLdMktTp);
    if (scwin.gLdMktTp === "1" || scwin.gLdMktTp === "2") {
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
        $c.cm.setColumnProp(grd_Grid, "MKT_NM", "Show", false);
        rdo_MKT_ID.setDisabled(true);
    } else {
        $c.cm.fn_com_isur_all(txb_ISUR_CD, txb_COM_NM);
        rdo_MKT_ID.setValue('9');
        rdo_MKT_ID.setDisabled(false);
        rdo_MKT_ID.addClass("TopCondition_Blue");
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF25106.txb_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF25106.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF25106.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name btn_ISUR_CD_onclick
 * @description btn_ISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ISUR_CD_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM); // 법인명 검색 팝업
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF25106.btn_ISUR_CD_onclick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF25106.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF25106.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF25106.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF25106.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF25106.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = cmb_PeriodTp.getValue();
        $c.stf.setFromToDate(vTp, edt_SDATE, edt_EDATE); // 기간선택 콤보박스
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF25106.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name btn_EDATE_onclick
 * @description btn_EDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDATE_onclick = function() {
    try {
        popUpCalendar2(edt_EDATE); // 공시일자-시작일 이미지 버튼 클릭 시 달력 팝업
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF25106.btn_EDATE_onclick" });
    }
};

/**
 * @method
 * @name btn_SDATE_onclick
